/* Small, dependency-free helpers shared by the game. */

export const TAU = Math.PI * 2;

export const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (v - a) / (b - a);
export const smoothstep = (a, b, v) => {
  const t = clamp((v - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
export const easeInOutCubic = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
export const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
export const angleTo = (x1, y1, x2, y2) => Math.atan2(y2 - y1, x2 - x1);

export function angleDelta(a, b) {
  let d = (b - a + Math.PI) % TAU;
  if (d < 0) d += TAU;
  return d - Math.PI;
}

export function lerpAngle(a, b, t) {
  return a + angleDelta(a, b) * t;
}

export function approach(current, target, delta) {
  if (current < target) return Math.min(current + delta, target);
  return Math.max(current - delta, target);
}

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function makeRng(seed) {
  const r = mulberry32(seed);
  const rng = () => r();
  rng.range = (a, b) => a + r() * (b - a);
  rng.int = (a, b) => Math.floor(a + r() * (b - a + 1));
  rng.pick = (arr) => arr[Math.floor(r() * arr.length)];
  rng.sign = () => (r() < 0.5 ? -1 : 1);
  return rng;
}

export function hexToRgb(hex) {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16);
  return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
}

export function rgbToHex({ r, g, b }) {
  const c = (v) => clamp(Math.round(v), 0, 255).toString(16).padStart(2, '0');
  return `#${c(r)}${c(g)}${c(b)}`;
}

export function mixHex(a, b, t) {
  const ca = hexToRgb(a);
  const cb = hexToRgb(b);
  return rgbToHex({
    r: lerp(ca.r, cb.r, t),
    g: lerp(ca.g, cb.g, t),
    b: lerp(ca.b, cb.b, t),
  });
}

export function rgba(hex, alpha = 1) {
  const { r, g, b } = hexToRgb(hex);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

export function luminance(hex) {
  const { r, g, b } = hexToRgb(hex);
  return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255;
}

/** Perceptually weighted RGB distance, tuned for the 8-colour palette. */
export function colorDistance(a, b) {
  const ca = hexToRgb(a);
  const cb = hexToRgb(b);
  const dr = ca.r - cb.r;
  const dg = ca.g - cb.g;
  const db = ca.b - cb.b;
  return Math.sqrt(dr * dr * 0.3 + dg * dg * 0.5 + db * db * 0.2) / 255;
}

export function colorScore(a, b, sigma = 0.22) {
  const d = colorDistance(a, b);
  return Math.exp(-((d / sigma) ** 2));
}

export function shade(hex, amount) {
  return mixHex(hex, amount > 0 ? '#ffffff' : '#000000', Math.abs(amount));
}

export function formatScore(n) {
  return Math.max(0, Math.round(n)).toLocaleString('en-US');
}

export function easeOutBack(t) {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
}

export function pointInPolygon(x, y, pts) {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const xi = pts[i].x;
    const yi = pts[i].y;
    const xj = pts[j].x;
    const yj = pts[j].y;
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function pathFromPoints(ctx, points, close = true) {
  if (!points.length) return;
  ctx.beginPath();
  ctx.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i++) ctx.lineTo(points[i].x, points[i].y);
  if (close) ctx.closePath();
}

export function smoothClosedPath(ctx, points) {
  if (!points.length) return;
  const n = points.length;
  const mid = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
  const start = mid(points[n - 1], points[0]);
  ctx.beginPath();
  ctx.moveTo(start.x, start.y);
  for (let i = 0; i < n; i++) {
    const p = points[i];
    const next = points[(i + 1) % n];
    const m = mid(p, next);
    ctx.quadraticCurveTo(p.x, p.y, m.x, m.y);
  }
  ctx.closePath();
}

export function dot(ctx, x, y, r) {
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TAU);
  ctx.fill();
}

export const reducedMotion = () =>
  typeof window !== 'undefined' && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

/* The grove: terrain, landmarks, decorations and sight-line helpers. */

import {
  TAU,
  clamp,
  dist,
  lerp,
  makeRng,
  mixHex,
  rgba,
  shade,
} from './utils.js';

export const WORLD = {
  w: 2000,
  h: 1300,
  bounds: { minX: 130, maxX: 1870, minY: 150, maxY: 1170 },
};

export const SHAPES = [
  {
    id: 'pool',
    name: 'Pool',
    hint: 'Flat and wide',
    speed: 0.8,
    icon: 'M7 20c3-7 11-9 18-7 7 2 11 7 10 10-1 4-9 6-17 5-8-1-13-4-11-8Z',
  },
  {
    id: 'mound',
    name: 'Mound',
    hint: 'Round and tall',
    speed: 0.9,
    icon: 'M12 4c5 0 8 5 9 10 1 5-3 8-9 8s-10-3-9-8c1-5 4-10 9-10Z',
  },
  {
    id: 'shard',
    name: 'Shard',
    hint: 'Sharp and lean',
    speed: 0.96,
    icon: 'M12 2 20 12l-5 12H9L4 12 12 2Z',
  },
  {
    id: 'tuft',
    name: 'Tuft',
    hint: 'Lobed and leafy',
    speed: 1.04,
    icon: 'M10 21c-5-2-7-7-4-11 1-2 4-3 6-2 1-4 7-5 9-1 2 3 1 6-1 8 4 1 4 5 1 7-3 2-8 1-11-1Z',
