242: function blobPoints(rng, radius, count = 24, irregularity = 0.13, rx = 1, ry = 1) {
243:   const pts = [];
244:   const phases = Array.from({ length: 4 }, () => rng.range(0, TAU));
245:   for (let i = 0; i < count; i++) {
246:     const a = (i / count) * TAU;
247:     const wobble =
248:       Math.sin(a * 2 + phases[0]) * 0.5 +
249:       Math.sin(a * 3 + phases[1]) * 0.3 +
250:       Math.sin(a * 5 + phases[2]) * 0.2;
251:     const r = radius * (1 + wobble * irregularity);
252:     pts.push({ x: Math.cos(a) * r * rx, y: Math.sin(a) * r * ry, a });
253:   }
254:   return pts;
255: }
