257: function insideEllipse(rng, radius, ySquash = 0.92) {
258:   const a = rng.range(0, TAU);
259:   const d = Math.sqrt(rng()) * radius * 0.94;
260:   return { x: Math.cos(a) * d, y: Math.sin(a) * d * ySquash, a };
261: }
