263: function makeZonePattern(zone, rng) {
264:   const r = zone.r;
265:   const data = { specks: [], strokes: [], rings: [], caps: [], cracks: [], grains: [] };
266:   if (zone.pattern === 'moss') {
267:     for (let i = 0; i < 96; i++) {
268:       const p = insideEllipse(rng, r);
269:       data.strokes.push({
270:         ...p,
271:         len: rng.range(5, 17),
272:         lean: rng.range(-0.65, 0.65),
273:         tone: rng.pick([0.16, 0.24, 0.32, 0.1]),
274:       });
275:     }
276:     for (let i = 0; i < 34; i++) {
277:       const p = insideEllipse(rng, r);
278:       data.specks.push({ ...p, size: rng.range(1.2, 3.4), tone: rng.range(0, 1) });
279:     }
280:     for (let i = 0; i < 12; i++) {
281:       const p = insideEllipse(rng, r * 0.8);
282:       data.caps.push({ ...p, size: rng.range(3, 7), rot: rng.range(-0.4, 0.4), kind: rng.int(0, 2) });
283:     }
284:   } else if (zone.pattern === 'sand') {
285:     for (let i = 0; i < 150; i++) {
286:       const p = insideEllipse(rng, r);
287:       data.grains.push({ ...p, size: rng.range(0.6, 1.8), tone: rng.range(0, 1) });
288:     }
289:     for (let i = 0; i < 16; i++) {
290:       const p = insideEllipse(rng, r);
291:       data.rings.push({
292:         x: p.x,
293:         y: p.y,
294:         rx: rng.range(35, 110),
295:         ry: rng.range(6, 16),
296:         rot: rng.range(-0.5, 0.5),
297:         tone: rng.range(0, 1),
298:       });
299:     }
300:     for (let i = 0; i < 16; i++) {
301:       const p = insideEllipse(rng, r * 0.9);
302:       data.specks.push({ ...p, size: rng.range(1.4, 3.2), tone: rng.range(0, 1) });
303:     }
304:   } else if (zone.pattern === 'stone') {
305:     for (let i = 0; i < 22; i++) {
306:       const p = insideEllipse(rng, r * 0.94);
307:       const size = rng.range(16, 42);
308:       const sides = rng.int(4, 6);
309:       const pts = [];
310:       for (let s = 0; s < sides; s++) {
311:         const a = (s / sides) * TAU + rng.range(-0.18, 0.18);
312:         pts.push({ x: p.x + Math.cos(a) * size * rng.range(0.7, 1.2), y: p.y + Math.sin(a) * size * rng.range(0.5, 0.9) });
313:       }
314:       data.cracks.push({ pts, tone: rng.range(0.4, 1) });
315:     }
316:     for (let i = 0; i < 90; i++) {
317:       const p = insideEllipse(rng, r);
318:       data.specks.push({ ...p, size: rng.range(0.7, 2.4), tone: rng.range(0, 1) });
319:     }
320:     for (let i = 0; i < 9; i++) {
321:       const p = insideEllipse(rng, r * 0.6);
322:       data.rings.push({ x: p.x, y: p.y, rx: rng.range(22, 70), ry: rng.range(8, 22), rot: rng.range(-0.9, 0.9), tone: rng.range(0, 1) });
323:     }
324:   } else if (zone.pattern === 'water') {
325:     for (let i = 0; i < 20; i++) {
326:       const p = insideEllipse(rng, r);
327:       data.rings.push({
328:         x: p.x,
329:         y: p.y,
330:         rx: rng.range(28, 120),
331:         ry: rng.range(6, 20),
332:         rot: rng.range(-0.35, 0.35),
333:         phase: rng.range(0, TAU),
334:         tone: rng.range(0, 1),
335:       });
336:     }
337:     for (let i = 0; i < 45; i++) {
338:       const p = insideEllipse(rng, r);
339:       data.specks.push({ ...p, size: rng.range(1, 3.6), tone: rng.range(0, 1), phase: rng.range(0, TAU) });
340:     }
341:     for (let i = 0; i < 13; i++) {
342:       const p = insideEllipse(rng, r * 0.85);
343:       data.strokes.push({ ...p, len: rng.range(12, 36), lean: rng.range(-0.2, 0.2), tone: rng.range(0, 1) });
344:     }
345:   } else if (zone.pattern === 'ember') {
346:     for (let i = 0; i < 18; i++) {
347:       const start = insideEllipse(rng, r * 0.9);
348:       const pts = [{ x: start.x, y: start.y }];
349:       let x = start.x;
350:       let y = start.y;
351:       const steps = rng.int(3, 6);
352:       for (let s = 0; s < steps; s++) {
353:         x += rng.range(-55, 55);
