355:         pts.push({ x, y });
356:       }
357:       data.cracks.push({ pts, tone: rng.range(0.45, 1), width: rng.range(1, 2.6) });
358:     }
359:     for (let i = 0; i < 70; i++) {
360:       const p = insideEllipse(rng, r);
361:       data.specks.push({ ...p, size: rng.range(0.8, 2.8), tone: rng.range(0, 1), phase: rng.range(0, TAU) });
362:     }
363:     for (let i = 0; i < 10; i++) {
364:       const p = insideEllipse(rng, r * 0.8);
365:       data.rings.push({ x: p.x, y: p.y, rx: rng.range(24, 64), ry: rng.range(10, 26), rot: rng.range(-0.8, 0.8), tone: rng.range(0, 1) });
366:     }
367:   } else if (zone.pattern === 'glowcap') {
368:     for (let i = 0; i < 24; i++) {
369:       const p = insideEllipse(rng, r * 0.9);
370:       data.caps.push({
371:         ...p,
372:         size: rng.range(5, 16),
373:         rot: rng.range(-0.5, 0.5),
374:         hue: rng.range(0, 1),
375:       });
