377:     for (let i = 0; i < 9; i++) {
378:       const p = insideEllipse(rng, r * 0.72);
379:       data.rings.push({ x: p.x, y: p.y, rx: rng.range(30, 85), ry: rng.range(9, 27), rot: rng.range(-0.6, 0.6), phase: rng.range(0, TAU), tone: rng.range(0, 1) });
380:     }
381:     for (let i = 0; i < 42; i++) {
382:       const p = insideEllipse(rng, r);
383:       data.specks.push({ ...p, size: rng.range(0.8, 2.8), tone: rng.range(0, 1), phase: rng.range(0, TAU) });
384:     }
385:   }
386:   return data;
