389: function buildWorld() {
390:   ZONES.forEach((zone, i) => {
391:     const rng = makeRng(9151 + i * 137);
392:     zone.points = blobPoints(rng, zone.r, 30, 0.11).map((p) => ({ x: zone.x + p.x, y: zone.y + p.y }));
393:     zone.inner = blobPoints(rng, zone.r * 0.84, 26, 0.14).map((p) => ({ x: zone.x + p.x, y: zone.y + p.y }));
394:     zone.patternData = makeZonePattern(zone, rng);
395:   });
396: 
397:   OBSTACLES.forEach((o) => {
398:     const rng = makeRng(o.seed * 977);
399:     o.points = blobPoints(rng, o.r, 16, 0.16, 1, 0.86).map((p) => ({ x: o.x + p.x, y: o.y + p.y }));
400:     for (let i = 0; i < 5; i++) {
401:       const p = insideEllipse(rng, o.r * 0.8, 0.7);
402:       o.mossPatches.push({ ...p, rx: rng.range(o.r * 0.18, o.r * 0.42), ry: rng.range(o.r * 0.08, o.r * 0.2), rot: rng.range(-0.4, 0.4) });
403:     }
404:   });
405: 
406:   // Ground-level detail: painted before characters.
407:   const rng = makeRng(44121);
408:   const nearObstacle = (x, y, pad = 10) => OBSTACLES.some((o) => dist(x, y, o.x, o.y) < o.r + pad);
409:   const nearSpawn = (x, y, pad = 90) => dist(x, y, 1000, 690) < pad;
410:   const nearZoneCenter = (x, y, factor = 0.5) => ZONES.some((z) => dist(x, y, z.x, z.y) < z.r * factor);
411: 
412:   for (let i = 0; i < 150; i++) {
413:     const x = rng.range(140, 1860);
414:     const y = rng.range(160, 1160);
415:     if (nearObstacle(x, y, 16) || nearSpawn(x, y, 60)) continue;
416:     GROUND_DETAILS.push({
417:       type: rng.pick(['grass', 'grass', 'grass', 'clover', 'pebble', 'flower', 'twig']),
418:       x,
419:       y,
420:       scale: rng.range(0.55, 1.45),
421:       phase: rng.range(0, TAU),
422:       tone: rng.range(0, 1),
423:       rot: rng.range(0, TAU),
424:     });
425:   }
426: 
427:   const tallTypes = ['fern', 'fern', 'mushroom', 'shrub', 'reed', 'rock', 'flower'];
428:   for (let i = 0; i < 62; i++) {
429:     const x = rng.range(145, 1855);
430:     const y = rng.range(175, 1140);
431:     if (nearObstacle(x, y, 30) || nearSpawn(x, y, 70) || nearZoneCenter(x, y, 0.45)) continue;
432:     const type = rng.pick(tallTypes);
433:     DECOR.push({
434:       type,
435:       x,
436:       y,
437:       scale: rng.range(0.7, 1.5),
438:       phase: rng.range(0, TAU),
439:       tone: rng.range(0, 1),
440:       lean: rng.range(-0.25, 0.25),
441:       rot: rng.range(0, TAU),
442:       layer: 'tall',
443:     });
444:   }
445: 
446:   // A few tall reeds hugging the water's edge.
447:   const tide = ZONES.find((z) => z.id === 'tide');
448:   for (let i = 0; i < 16; i++) {
449:     const a = rng.range(0, TAU);
450:     const d = tide.r * rng.range(0.78, 1.08);
451:     DECOR.push({
452:       type: rng.pick(['reed', 'reed', 'fern']),
453:       x: tide.x + Math.cos(a) * d,
454:       y: tide.y + Math.sin(a) * d * 0.72,
455:       scale: rng.range(0.8, 1.35),
456:       phase: rng.range(0, TAU),
457:       tone: rng.range(0, 1),
458:       lean: rng.range(-0.2, 0.2),
459:       rot: rng.range(0, TAU),
460:       layer: 'tall',
461:     });
462:   }
463: 
464:   // Tree ring. Trees beyond the clearing, with a handful leaning in.
465:   const treePositions = [];
466:   const edge = 165;
467:   for (let i = 0; i < 44; i++) {
468:     const a = (i / 44) * TAU + rng.range(-0.045, 0.045);
469:     const rad = rng.range(0.94, 1.16);
470:     const x = 1000 + Math.cos(a) * 1110 * rad;
471:     const y = 650 + Math.sin(a) * 720 * rad;
472:     treePositions.push({ x, y });
473:   }
474:   for (let i = 0; i < 13; i++) {
475:     const side = rng.int(0, 3);
476:     let x;
477:     let y;
478:     if (side === 0) {
479:       x = rng.range(120, 1880);
480:       y = rng.range(90, edge);
481:     } else if (side === 1) {
482:       x = rng.range(120, 1880);
483:       y = rng.range(WORLD.h - edge + 20, WORLD.h - 10);
484:     } else if (side === 2) {
485:       x = rng.range(20, edge);
486:       y = rng.range(120, 1180);
487:     } else {
488:       x = rng.range(WORLD.w - edge, WORLD.w - 10);
489:       y = rng.range(120, 1180);
490:     }
491:     treePositions.push({ x, y });
492:   }
493:   treePositions.forEach((p, i) => {
494:     const r = makeRng(700 + i * 31);
495:     TREES.push({
496:       x: p.x,
497:       y: p.y,
498:       scale: r.range(0.85, 1.55),
499:       lean: r.range(-0.17, 0.17),
500:       hue: r.range(0, 1),
501:       phase: r.range(0, TAU),
502:       seed: i,
503:     });
504:   });
505: 
506:   for (let i = 0; i < 54; i++) {
507:     FIREFLIES.push({
508:       x: rng.range(100, 1900),
509:       y: rng.range(120, 1200),
510:       phase: rng.range(0, TAU),
511:       radius: rng.range(16, 80),
512:       speed: rng.range(0.08, 0.28),
513:       size: rng.range(0.9, 2.2),
514:       tone: rng.range(0, 1),
515:     });
516:   }
517: }
