651: export function rayCast(x, y, angle, maxDist = 2000, inflate = 0) {
652:   const dx = Math.cos(angle);
653:   const dy = Math.sin(angle);
654:   let nearest = maxDist;
655:   for (const o of OBSTACLES) {
656:     const r = o.r + inflate;
657:     const ox = x - o.x;
658:     const oy = y - o.y;
659:     const b = ox * dx + oy * dy;
660:     const c = ox * ox + oy * oy - r * r;
661:     const disc = b * b - c;
662:     if (disc < 0) continue;
663:     const root = Math.sqrt(disc);
664:     const t = -b - root;
665:     if (t > 0 && t < nearest) nearest = t;
666:   }
667:   return nearest;
668: }
