/* ================================================================
   Slime & Seek — a moonlit field guide to being furniture
   ================================================================ */

@font-face {
  font-family: 'Fraunces';
  src: url('./assets/fonts/fraunces-500.woff2') format('woff2');
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Fraunces';
  src: url('./assets/fonts/fraunces-600.woff2') format('woff2');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Outfit';
  src: url('./assets/fonts/outfit-300.woff2') format('woff2');
  font-weight: 300;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Outfit';
  src: url('./assets/fonts/outfit-400.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Outfit';
  src: url('./assets/fonts/outfit-500.woff2') format('woff2');
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Outfit';
  src: url('./assets/fonts/outfit-600.woff2') format('woff2');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Outfit';
  src: url('./assets/fonts/outfit-700.woff2') format('woff2');
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

:root {
  --ink: #08110d;
  --ink-2: #0c1a13;
  --panel: rgba(9, 19, 14, 0.84);
  --panel-soft: rgba(13, 26, 19, 0.7);
  --line: rgba(207, 231, 190, 0.16);
  --line-strong: rgba(207, 231, 190, 0.3);
  --cream: #eef2dd;
  --muted: #a9b9a1;
  --faint: #7b8e7c;
  --moss: #9fce7f;
  --moss-deep: #3e6a45;
  --amber: #ecc47d;
  --amber-deep: #9c6e30;
  --rose: #ea9a79;
  --blue: #8fc2c8;
  --radius: 18px;
  --radius-sm: 12px;
  --font-display: 'Fraunces', Georgia, serif;
  --font-ui: 'Outfit', 'Segoe UI', sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: #07100d;
  color: var(--cream);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  position: fixed;
  inset: 0;
  overscroll-behavior: none;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  padding: 0;
  background: none;
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible {
  outline: 2px solid var(--amber);
  outline-offset: 3px;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  isolation: isolate;
  overflow: hidden;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  z-index: 0;
  touch-action: none;
}

.screen-grain {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: 0.19;
  mix-blend-mode: soft-light;
  background-image: radial-gradient(rgba(255, 255, 255, 0.5) 0.45px, transparent 0.45px);
  background-size: 3px 3px;
}

.is-hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

/* ================================================================
   Shared little typography bits
   ================================================================ */

.eyebrow,
.field-mark {
  display: inline-block;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.23em;
  text-transform: uppercase;
  color: var(--muted);
  white-space: nowrap;
}

.field-mark {
  color: var(--amber);
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 17px;
  padding: 0 5px;
  border: 1px solid rgba(223, 241, 201, 0.28);
  border-bottom-color: rgba(223, 241, 201, 0.15);
  border-radius: 4px;
  background: rgba(207, 231, 190, 0.08);
  color: var(--cream);
  font-family: var(--font-ui);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.04em;
  line-height: 1;
  vertical-align: 1px;
}

.text-btn {
  position: relative;
  color: var(--muted);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  padding: 6px 0;
  transition: color 0.2s ease;
}

.text-btn::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: 2px;
  height: 1px;
  background: currentColor;
  transform: scaleX(0.3);
  transform-origin: left;
  opacity: 0.5;
  transition: transform 0.3s ease;
}

.text-btn:hover {
  color: var(--cream);
}

.text-btn:hover::after {
  transform: scaleX(1);
}

/* ================================================================
   HUD
   ================================================================ */

.hud {
  position: absolute;
  z-index: 12;
  top: calc(14px + var(--safe-top));
  left: calc(18px + var(--safe-left));
  right: calc(18px + var(--safe-right));
  display: grid;
  grid-template-columns: minmax(200px, 1fr) auto minmax(200px, 1fr);
  align-items: start;
  gap: 16px;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.hud-left {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 2px;
}

.team-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  padding: 5px 10px 5px 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(7, 16, 12, 0.56);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.17em;
  color: var(--cream);
}

.team-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--moss);
  box-shadow: 0 0 9px rgba(159, 206, 127, 0.85);
}

body[data-role='seeker'] .team-dot {
  background: var(--amber);
  box-shadow: 0 0 9px rgba(236, 196, 125, 0.85);
}

.objective {
  margin: 0;
  max-width: 280px;
  color: rgba(238, 242, 221, 0.7);
  font-size: 11px;
  font-weight: 300;
  line-height: 1.4;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.8);
}

.clock-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 150px;
  padding: 8px 18px 9px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(7, 16, 12, 0.67);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
}

.clock-label {
  margin-bottom: 1px;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.22em;
  color: var(--faint);
}

.clock {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
  color: var(--cream);
}

body[data-role='seeker'] .clock {
  color: var(--amber);
}

.clock-wrap.urgent .clock {
  color: var(--rose);
  animation: clock-pulse 1s ease-in-out infinite;
}

@keyframes clock-pulse {
  50% {
    opacity: 0.58;
  }
}

.team-dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 8px;
  margin-top: 6px;
}

.team-dots i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--moss);
  opacity: 0.8;
  transition: opacity 0.3s, background 0.3s;
}

.team-dots i.caught {
  background: rgba(234, 154, 121, 0.35);
  opacity: 0.7;
}

.hud-right {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  pointer-events: auto;
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(7, 16, 12, 0.56);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: var(--muted);
  transition: color 0.2s, border-color 0.2s, background 0.2s, transform 0.2s;
}

.icon-btn:hover {
  color: var(--cream);
  border-color: var(--line-strong);
  background: rgba(19, 34, 24, 0.9);
  transform: translateY(-1px);
}

.icon-btn svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
}

.icon-btn.muted .sound-wave {
  opacity: 0.18;
}

/* ================================================================
   Countdown, toast, hint
   ================================================================ */

.countdown {
  position: absolute;
  z-index: 16;
  top: 42%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-display);
  font-size: clamp(72px, 14vw, 150px);
  font-weight: 500;
  line-height: 1;
  color: var(--cream);
  text-shadow: 0 10px 50px rgba(0, 0, 0, 0.55);
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.countdown small {
  display: block;
  margin-top: 8px;
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.3em;
  text-align: center;
  color: var(--amber);
}

.toast {
  position: absolute;
  z-index: 18;
  top: calc(86px + var(--safe-top));
  left: 50%;
  transform: translate(-50%, -8px);
  max-width: min(440px, calc(100vw - 28px));
  padding: 8px 15px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(8, 18, 13, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  color: var(--cream);
  font-size: 11px;
  font-weight: 400;
  letter-spacing: 0.02em;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ================================================================
   Lower controls
   ================================================================ */

.lower-controls {
  position: absolute;
  z-index: 14;
  left: calc(16px + var(--safe-left));
  right: calc(16px + var(--safe-right));
  bottom: calc(14px + var(--safe-bottom));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.hint {
  position: absolute;
  left: 50%;
  bottom: 4px;
  transform: translateX(-50%);
  max-width: min(660px, calc(100vw - 420px));
  padding: 7px 13px;
  border-radius: 999px;
  background: rgba(6, 14, 10, 0.5);
  color: rgba(238, 242, 221, 0.66);
  font-size: 10px;
  font-weight: 300;
  letter-spacing: 0.02em;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
}

.hint b,
.hint strong {
  color: var(--cream);
  font-weight: 500;
}

.mode-btn {
  pointer-events: auto;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-width: 144px;
  height: 52px;
  padding: 0 15px;
  border: 1px solid rgba(207, 231, 190, 0.24);
  border-radius: 15px;
  background: rgba(9, 20, 14, 0.86);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  color: var(--cream);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.25);
  transition: background 0.2s ease, transform 0.2s ease, border-color 0.2s ease;
}

.mode-btn:hover {
  background: rgba(21, 39, 26, 0.94);
  border-color: rgba(207, 231, 190, 0.42);
  transform: translateY(-1px);
}

.mode-btn kbd {
  margin-left: auto;
}

.mode-btn.disguise {
  border-color: rgba(236, 196, 125, 0.46);
  background: rgba(63, 53, 27, 0.88);
}

.mode-btn.disguise .mode-icon {
  color: var(--amber);
  transform: rotate(180deg);
}

.mode-icon {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border-radius: 50%;
  background: rgba(207, 231, 190, 0.1);
  color: var(--moss);
  font-size: 15px;
  transition: transform 0.35s ease, color 0.2s ease;
}

body[data-role='seeker'] .mode-btn {
  display: none;
}

/* ================================================================
   Joystick
   ================================================================ */

.joystick {
  display: none;
  position: relative;
  flex: 0 0 auto;
  width: 126px;
  height: 126px;
  border-radius: 50%;
  touch-action: none;
  pointer-events: auto;
  opacity: 0.9;
}

.joystick-ring {
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(207, 231, 190, 0.26);
  border-radius: 50%;
  background: radial-gradient(circle at 50% 45%, rgba(207, 231, 190, 0.07), rgba(6, 15, 10, 0.34) 66%);
  box-shadow: inset 0 0 30px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

.joystick-knob {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  border: 1px solid rgba(221, 243, 201, 0.35);
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, rgba(201, 232, 167, 0.36), rgba(31, 57, 38, 0.9) 72%);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.32), 0 0 0 6px rgba(207, 231, 190, 0.04);
  transition: transform 0.05s linear;
}

.joy-arrow {
  position: absolute;
  font-size: 8px;
  color: rgba(238, 242, 221, 0.32);
  pointer-events: none;
}

.joy-arrow.up {
  top: 2px;
  left: 50%;
  transform: translateX(-50%);
}
.joy-arrow.down {
  bottom: 2px;
  left: 50%;
  transform: translateX(-50%);
}
.joy-arrow.left {
  left: 2px;
  top: 50%;
  transform: translateY(-50%);
}
.joy-arrow.right {
  right: 2px;
  top: 50%;
  transform: translateY(-50%);
}

/* ================================================================
   Hider disguise tray
   ================================================================ */

.hider-panel {
  position: absolute;
  z-index: 13;
  left: calc(16px + var(--safe-left));
  bottom: calc(74px + var(--safe-bottom));
  width: min(790px, calc(100vw - 210px));
  padding: 11px 12px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--panel);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.035);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.camo-strip {
  display: grid;
  grid-template-columns: auto minmax(90px, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 1px 3px 9px;
  border-bottom: 1px solid rgba(207, 231, 190, 0.09);
}

.camo-readout {
  display: flex;
  align-items: baseline;
  gap: 7px;
  min-width: 78px;
}

.camo-readout strong {
  font-family: var(--font-display);
  font-size: 27px;
  font-weight: 500;
  line-height: 0.9;
  color: var(--moss);
  font-variant-numeric: tabular-nums;
  transition: color 0.4s ease;
}

.camo-readout strong small {
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0;
  color: var(--muted);
  margin-left: 1px;
}

.camo-track {
  position: relative;
  height: 5px;
  border-radius: 999px;
  background: rgba(207, 231, 190, 0.1);
  overflow: hidden;
}

.camo-track i {
  position: absolute;
  inset: 0;
  transform: scaleX(0);
  transform-origin: left;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--rose), var(--amber) 48%, var(--moss));
  box-shadow: 0 0 12px rgba(159, 206, 127, 0.5);
  transition: transform 0.25s ease, background 0.3s ease;
}

.camo-target {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
  min-width: 96px;
  text-align: right;
}

.camo-target span:last-child {
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--cream);
  font-size: 10px;
  font-weight: 400;
}

.disguise-tray {
  display: grid;
  grid-template-columns: minmax(190px, 1fr) minmax(240px, 1.1fr) auto;
  gap: 14px;
  align-items: stretch;
  padding-top: 10px;
}

.tray-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
}

.tray-value {
  color: rgba(238, 242, 221, 0.72);
  font-size: 9px;
  font-weight: 400;
}

.shape-bar {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 4px;
}

.shape-chip {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  height: 52px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: rgba(207, 231, 190, 0.035);
  color: var(--muted);
  transition: background 0.2s, border-color 0.2s, color 0.2s, transform 0.2s;
}

.shape-chip:hover {
  background: rgba(207, 231, 190, 0.08);
  color: var(--cream);
}

.shape-chip.active {
  border-color: rgba(159, 206, 127, 0.48);
  background: rgba(159, 206, 127, 0.12);
  color: var(--cream);
  box-shadow: inset 0 0 18px rgba(159, 206, 127, 0.07);
}

.shape-chip.locked {
  opacity: 0.44;
}

.shape-chip.locked::after {
  content: '';
  position: absolute;
  top: 4px;
  right: 4px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--faint);
}

.shape-chip svg {
  width: 21px;
  height: 21px;
  fill: currentColor;
}

.shape-chip span {
  font-size: 7.5px;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.paint-row {
  display: flex;
  align-items: stretch;
  gap: 8px;
}

.paint-studio {
  position: relative;
  flex: 0 0 auto;
  width: 62px;
  height: 62px;
  border: 1px solid rgba(207, 231, 190, 0.2);
  border-radius: 10px;
  overflow: hidden;
  background: #12251b;
  box-shadow: inset 0 0 14px rgba(0, 0, 0, 0.35);
  cursor: crosshair;
}

.paint-studio canvas {
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.brush-hint {
  position: absolute;
  left: 50%;
  bottom: 3px;
  transform: translateX(-50%);
  padding: 1px 5px;
  border-radius: 999px;
  background: rgba(3, 9, 6, 0.55);
  color: rgba(238, 242, 221, 0.52);
  font-size: 6px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  pointer-events: none;
}

.paint-tools {
  display: flex;
  flex: 1;
  flex-direction: column;
  justify-content: space-between;
  gap: 5px;
  min-width: 0;
}

.palette {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 3px;
}

.palette button {
  position: relative;
  aspect-ratio: 1;
  min-width: 0;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 50%;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.palette button:hover {
  transform: scale(1.13);
}

.palette button.active {
  border-color: var(--cream);
  box-shadow: 0 0 0 2px rgba(9, 19, 14, 0.9), 0 0 0 3px rgba(238, 242, 221, 0.55);
  transform: scale(1.05);
}

.paint-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.mini-btn {
  height: 20px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(207, 231, 190, 0.055);
  color: rgba(238, 242, 221, 0.72);
  font-size: 7.5px;
  font-weight: 500;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  transition: background 0.2s, color 0.2s;
  white-space: nowrap;
}

.mini-btn:hover {
  background: rgba(207, 231, 190, 0.12);
  color: var(--cream);
}

.ground-swatch {
  position: relative;
  width: 28px;
  height: 20px;
  border: 1px solid rgba(207, 231, 190, 0.22);
  border-radius: 5px;
  overflow: hidden;
  flex: 0 0 auto;
}

.ground-swatch::after {
  content: 'ground';
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: rgba(5, 12, 8, 0.35);
  color: rgba(255, 255, 255, 0.74);
  font-size: 5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.ground-swatch canvas {
  width: 100%;
  height: 100%;
  display: block;
}

.action-column {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 6px;
  width: 106px;
}

.action-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 31px;
  padding: 0 9px;
  border: 1px solid rgba(207, 231, 190, 0.26);
  border-radius: 9px;
  background: rgba(159, 206, 127, 0.11);
  color: var(--cream);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.01em;
  overflow: hidden;
  transition: background 0.2s, border-color 0.2s, transform 0.2s;
}

.action-btn:hover {
  background: rgba(159, 206, 127, 0.19);
  border-color: rgba(207, 231, 190, 0.44);
  transform: translateY(-1px);
}

.action-btn:active {
  transform: translateY(0);
}

.action-btn.secondary {
  background: rgba(207, 231, 190, 0.06);
}

.action-btn.warm {
  border-color: rgba(236, 196, 125, 0.4);
  background: rgba(236, 196, 125, 0.14);
}

.action-btn kbd {
  margin-left: auto;
  height: 15px;
  min-width: 16px;
  font-size: 7px;
  opacity: 0.8;
}

.action-icon {
  display: inline-grid;
  place-items: center;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  color: var(--moss);
  font-size: 10px;
  flex: 0 0 auto;
}

.action-btn.warm .action-icon {
  color: var(--amber);
}

.action-btn.secondary .action-icon {
  color: var(--amber);
}

/* ================================================================
   Seeker panel
   ================================================================ */

.seeker-panel {
  position: absolute;
  z-index: 13;
  right: calc(16px + var(--safe-right));
  bottom: calc(74px + var(--safe-bottom));
  display: flex;
  align-items: flex-end;
  gap: 14px;
  width: min(560px, calc(100vw - 200px));
  padding: 11px 12px;
  border: 1px solid rgba(236, 196, 125, 0.2);
  border-radius: var(--radius);
  background: var(--panel);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.32);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.seeker-status {
  flex: 0 0 128px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 2px 12px 2px 3px;
  border-right: 1px solid rgba(236, 196, 125, 0.16);
}

.seeker-status strong {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 500;
  line-height: 1;
  color: var(--amber);
  font-variant-numeric: tabular-nums;
}

.tag-pips {
  display: flex;
  gap: 4px;
  margin-top: 5px;
}

.tag-pips i {
  width: 14px;
  height: 3px;
  border-radius: 99px;
  background: rgba(236, 196, 125, 0.2);
}

.tag-pips i.on {
  background: var(--amber);
  box-shadow: 0 0 8px rgba(236, 196, 125, 0.5);
}

.seeker-actions {
  flex: 1;
  display: grid;
  grid-template-columns: 1.35fr 0.8fr;
  gap: 7px;
}

.seeker-actions .action-btn {
  min-height: 47px;
  padding: 0 12px;
  border-radius: 10px;
  font-size: 10px;
}

.seeker-actions .action-btn kbd {
  margin-left: auto;
}

.cooldown {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: var(--amber);
  transform-origin: left;
  opacity: 0.8;
}

/* ================================================================
   Full screens
   ================================================================ */

.screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  transition: opacity 0.45s ease, visibility 0.45s ease;
}

/* ================================================================
   Title
   ================================================================ */

.title-screen {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4vw;
  padding: calc(44px + var(--safe-top)) max(5vw, 34px) calc(30px + var(--safe-bottom));
  background:
    radial-gradient(ellipse at 18% 46%, rgba(15, 37, 24, 0.28), transparent 55%),
    linear-gradient(90deg, rgba(4, 11, 8, 0.82) 0%, rgba(5, 13, 9, 0.62) 43%, rgba(5, 13, 9, 0.18) 74%, rgba(5, 13, 9, 0.44) 100%);
}

.title-screen::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(0deg, rgba(3, 8, 6, 0.62), transparent 34%);
}

.title-top {
  position: absolute;
  z-index: 2;
  top: calc(26px + var(--safe-top));
  left: max(5vw, 34px);
  right: max(5vw, 34px);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.title-main {
  position: relative;
  z-index: 2;
  width: min(720px, 58vw);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  margin-left: 2vw;
}

.kicker {
  margin: 0 0 12px 6px;
  color: var(--amber);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.32em;
}

.wordmark {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0 0.14em;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(4.4rem, 8.3vw, 8.2rem);
  font-weight: 500;
  line-height: 0.84;
  letter-spacing: -0.055em;
  color: var(--cream);
  text-shadow: 0 18px 60px rgba(0, 0, 0, 0.45);
}

.wordmark em {
  display: inline-block;
  color: var(--amber);
  font-size: 0.72em;
  font-weight: 500;
  letter-spacing: -0.02em;
  transform: translateY(-0.04em) rotate(-3deg);
}

.lede {
  max-width: 460px;
  margin: 17px 0 2px 6px;
  color: rgba(238, 242, 221, 0.68);
  font-size: clamp(12px, 1.05vw, 15px);
  font-weight: 300;
  line-height: 1.55;
  letter-spacing: 0.01em;
}

.role-select {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  width: 100%;
  max-width: 660px;
  margin-top: 24px;
}

.role-card {
  position: relative;
  display: grid;
  grid-template-columns: 58px 1fr;
  align-items: center;
  gap: 11px;
  min-height: 100px;
  padding: 12px 14px 12px 10px;
  border: 1px solid rgba(207, 231, 190, 0.16);
  border-radius: 14px;
  background: rgba(8, 20, 13, 0.47);
  text-align: left;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  transition: border-color 0.25s ease, background 0.25s ease, transform 0.25s ease;
}

.role-card:hover {
  border-color: rgba(207, 231, 190, 0.36);
  background: rgba(13, 28, 19, 0.67);
  transform: translateY(-2px);
}

.role-card.selected {
  border-color: rgba(159, 206, 127, 0.6);
  background: rgba(26, 48, 30, 0.62);
  box-shadow: inset 0 0 26px rgba(159, 206, 127, 0.055), 0 14px 30px rgba(0, 0, 0, 0.18);
}

.role-card[data-role='seeker'].selected {
  border-color: rgba(236, 196, 125, 0.62);
  background: rgba(51, 41, 22, 0.6);
  box-shadow: inset 0 0 26px rgba(236, 196, 125, 0.06), 0 14px 30px rgba(0, 0, 0, 0.18);
}

.role-art {
  display: grid;
  place-items: center;
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: rgba(159, 206, 127, 0.09);
  border: 1px solid rgba(159, 206, 127, 0.17);
  overflow: hidden;
}

.role-art svg {
  width: 50px;
  height: 40px;
  fill: rgba(181, 218, 166, 0.82);
  stroke: rgba(217, 240, 201, 0.7);
  stroke-width: 1.2;
  stroke-linecap: round;
}

.seeker-art {
  background: rgba(236, 196, 125, 0.07);
  border-color: rgba(236, 196, 125, 0.18);
}

.seeker-art svg {
  fill: rgba(107, 88, 52, 0.85);
  stroke: rgba(246, 217, 160, 0.72);
}

.role-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.role-name {
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.01em;
  color: var(--cream);
}

.role-desc {
  color: rgba(238, 242, 221, 0.52);
  font-size: 9.5px;
  font-weight: 300;
  line-height: 1.4;
}

.role-tag {
  position: absolute;
  top: 11px;
  right: 11px;
  color: rgba(207, 231, 190, 0.4);
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.22em;
}

.role-card.selected .role-tag {
  color: var(--moss);
}

.role-card[data-role='seeker'].selected .role-tag {
  color: var(--amber);
}

.play-btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 196px;
  height: 55px;
  margin-top: 22px;
  padding: 0 42px;
  border: 1px solid rgba(225, 244, 201, 0.45);
  border-radius: 999px;
  background: linear-gradient(180deg, #d9edbf 0%, #b9d99a 100%);
  color: #142417;
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.55);
  transition: transform 0.22s ease, box-shadow 0.22s ease, filter 0.22s ease;
}

.play-btn::after {
  content: '→';
  position: absolute;
  right: 20px;
  top: 50%;
  transform: translateY(-52%);
  font-size: 16px;
  font-weight: 300;
  opacity: 0.55;
}

.play-btn:hover {
  transform: translateY(-2px);
  filter: brightness(1.05);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.36), inset 0 1px 0 rgba(255, 255, 255, 0.6);
}

.play-btn:active {
  transform: translateY(0);
}

.play-btn.small {
  min-width: 170px;
  height: 46px;
  margin-top: 0;
  padding: 0 30px;
  font-size: 11px;
}

.title-foot {
  display: flex;
  align-items: center;
  gap: 20px;
  margin: 17px 0 0 6px;
}

.mouse-hint {
  color: rgba(238, 242, 221, 0.44);
  font-size: 9px;
  font-weight: 300;
  letter-spacing: 0.02em;
}

.best-line {
  padding-left: 20px;
  border-left: 1px solid rgba(207, 231, 190, 0.16);
  color: var(--faint);
  font-size: 8px;
  font-weight: 500;
  letter-spacing: 0.16em;
}

.title-side {
  position: relative;
  z-index: 2;
  width: 220px;
  margin-right: 5vw;
  margin-top: auto;
  margin-bottom: 5vh;
  padding-left: 20px;
  border-left: 1px solid rgba(236, 196, 125, 0.26);
  text-align: left;
  opacity: 0.7;
}

.title-side p {
  margin: 0 0 12px;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 500;
  line-height: 1.45;
  color: rgba(238, 242, 221, 0.75);
}

.side-credit {
  color: var(--faint);
  font-size: 8px;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* ================================================================
   Field guide
   ================================================================ */

.guide-screen {
  display: grid;
  place-items: center;
  padding: calc(22px + var(--safe-top)) 18px calc(22px + var(--safe-bottom));
  background: rgba(3, 9, 6, 0.76);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.guide-book {
  width: min(900px, 100%);
  max-height: min(760px, calc(100vh - 60px));
  overflow: auto;
  padding: clamp(20px, 3vw, 36px);
  border: 1px solid rgba(236, 196, 125, 0.18);
  border-radius: 18px;
  background:
    radial-gradient(ellipse at 0% 0%, rgba(68, 50, 27, 0.22), transparent 44%),
    rgba(11, 23, 16, 0.94);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.45);
  scrollbar-width: thin;
  scrollbar-color: rgba(207, 231, 190, 0.2) transparent;
}

.guide-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
}

.guide-title-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin: 24px 0 22px;
}

.guide-title-row h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(34px, 5vw, 58px);
  font-weight: 500;
  line-height: 0.96;
  letter-spacing: -0.035em;
  color: var(--cream);
}

.specimen {
  color: var(--faint);
  font-size: 9px;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.specimen i {
  color: var(--amber);
  font-family: var(--font-display);
  font-size: 11px;
}

.guide-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 34px;
  row-gap: 20px;
}

.guide-grid article {
  position: relative;
  padding: 0 0 0 36px;
}

.guide-grid article::before {
  content: '';
  position: absolute;
  left: 0;
  top: 2px;
  width: 22px;
  height: 1px;
  background: rgba(236, 196, 125, 0.35);
}

.guide-num {
  position: absolute;
  left: 0;
  top: 7px;
  color: var(--amber);
  font-family: var(--font-display);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.06em;
}

.guide-grid h3 {
  margin: 0 0 5px;
  color: var(--cream);
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 500;
  letter-spacing: -0.01em;
}

.guide-grid p {
  margin: 0;
  color: rgba(238, 242, 221, 0.58);
  font-size: 10.5px;
  font-weight: 300;
  line-height: 1.55;
}

.guide-grid p strong {
  color: var(--moss);
  font-weight: 500;
}

.guide-foot {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px;
  margin-top: 28px;
  padding-top: 15px;
  border-top: 1px solid var(--line);
  color: var(--faint);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

/* ================================================================
   Pause & results
   ================================================================ */

.modal-screen {
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(3, 9, 6, 0.64);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.modal-card {
  width: min(520px, 100%);
  padding: clamp(28px, 5vw, 46px);
  border: 1px solid rgba(207, 231, 190, 0.18);
  border-radius: 20px;
  background:
    radial-gradient(ellipse at 15% 0%, rgba(79, 112, 70, 0.16), transparent 58%),
    rgba(9, 20, 14, 0.94);
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.5);
  text-align: center;
}

.modal-card h2 {
  margin: 11px 0 10px;
  font-family: var(--font-display);
  font-size: clamp(42px, 7vw, 66px);
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.04em;
  color: var(--cream);
}

.modal-card p {
  max-width: 370px;
  margin: 0 auto;
  color: rgba(238, 242, 221, 0.6);
  font-size: 12px;
  font-weight: 300;
  line-height: 1.55;
}

.modal-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 13px;
  margin-top: 28px;
}

.ghost-btn {
  min-width: 170px;
  height: 40px;
  padding: 0 22px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: rgba(238, 242, 221, 0.8);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}

.ghost-btn:hover {
  background: rgba(207, 231, 190, 0.08);
  border-color: var(--line-strong);
  color: var(--cream);
}

.results-card {
  width: min(620px, 100%);
  background:
    radial-gradient(ellipse at 50% -10%, rgba(126, 166, 100, 0.2), transparent 52%),
    rgba(9, 20, 14, 0.95);
}

.results-screen.loss .results-card {
  background:
    radial-gradient(ellipse at 50% -10%, rgba(176, 90, 60, 0.18), transparent 52%),
    rgba(16, 15, 11, 0.95);
}

.results-screen.loss .eyebrow {
  color: var(--rose);
}

.result-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin: 27px 0 0;
  padding: 16px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.result-stats div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.result-stats span {
  color: var(--faint);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

.result-stats strong {
  font-family: var(--font-display);
  font-size: 25px;
  font-weight: 500;
  line-height: 1;
  color: var(--cream);
  font-variant-numeric: tabular-nums;
}

.result-stats div:nth-child(2) strong {
  color: var(--moss);
}

.record-line {
  margin-top: 14px !important;
  color: var(--amber) !important;
  font-size: 9px !important;
  font-weight: 500 !important;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.results-card .modal-actions {
  margin-top: 22px;
}

.rotate-hint {
  position: absolute;
  z-index: 50;
  left: 50%;
  bottom: calc(12px + var(--safe-bottom));
  transform: translateX(-50%);
  display: none;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(8, 18, 13, 0.8);
  color: var(--faint);
  font-size: 8px;
  letter-spacing: 0.05em;
  pointer-events: none;
}

/* ================================================================
   Responsive
   ================================================================ */

@media (max-width: 1080px) {
  .title-side {
    display: none;
  }
  .title-main {
    width: min(720px, 82vw);
  }
  .hider-panel {
    width: min(760px, calc(100vw - 185px));
  }
  .disguise-tray {
    grid-template-columns: minmax(160px, 1fr) minmax(200px, 1fr) auto;
    gap: 10px;
  }
  .shape-bar {
    grid-template-columns: repeat(7, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  .title-screen {
    padding-left: 28px;
    padding-right: 28px;
  }
  .title-main {
    width: 100%;
    margin-left: 0;
  }
  .title-top {
    left: 28px;
    right: 28px;
  }
  .title-foot .mouse-hint {
    display: none;
  }
  .hud {
    grid-template-columns: 1fr auto auto;
    gap: 8px;
  }
  .objective {
    display: none;
  }
  .hider-panel {
    width: calc(100vw - 32px);
    left: 16px;
  }
  .mode-btn {
    position: absolute;
    right: 0;
    bottom: 0;
  }
  .hint {
    display: none;
  }
}

@media (max-width: 720px), (pointer: coarse) {
  .joystick {
    display: block;
  }
  .mode-btn {
    position: static;
  }
  .lower-controls {
    align-items: flex-end;
  }
  .hider-panel,
  .seeker-panel {
    bottom: calc(150px + var(--safe-bottom));
  }
  .hider-panel {
    left: calc(10px + var(--safe-left));
    right: calc(10px + var(--safe-right));
    width: auto;
    padding: 9px;
    border-radius: 15px;
  }
  .seeker-panel {
    left: calc(10px + var(--safe-left));
    right: calc(10px + var(--safe-right));
    width: auto;
    bottom: calc(150px + var(--safe-bottom));
    gap: 9px;
    padding: 9px;
  }
  .camo-strip {
    gap: 9px;
    padding-bottom: 7px;
  }
  .camo-readout {
    min-width: 64px;
  }
  .camo-readout strong {
    font-size: 23px;
  }
  .camo-target {
    min-width: 76px;
  }
  .camo-target span:last-child {
    max-width: 110px;
  }
  .disguise-tray {
    grid-template-columns: minmax(0, 1fr) 78px;
    grid-template-areas:
      'shape actions'
      'paint actions';
    gap: 8px;
  }
  .shape-column {
    grid-area: shape;
    min-width: 0;
  }
  .paint-column {
    grid-area: paint;
    min-width: 0;
  }
  .action-column {
    grid-area: actions;
    width: 78px;
    justify-content: flex-start;
  }
  .shape-bar {
    gap: 3px;
  }
  .shape-chip {
    height: 41px;
    border-radius: 7px;
  }
  .shape-chip svg {
    width: 16px;
    height: 16px;
  }
  .shape-chip span {
    font-size: 6px;
  }
  .tray-heading {
    margin-bottom: 4px;
  }
  .tray-value {
    display: none;
  }
  .paint-row {
    gap: 6px;
  }
  .paint-studio {
    width: 48px;
    height: 48px;
    border-radius: 8px;
  }
  .brush-hint {
    display: none;
  }
  .palette {
    gap: 2px;
  }
  .paint-actions {
    gap: 4px;
  }
  .mini-btn {
    height: 17px;
    padding: 0 6px;
    font-size: 6.5px;
  }
  .ground-swatch {
    width: 22px;
    height: 17px;
  }
  .action-btn {
    min-height: 27px;
    padding: 0 7px;
    font-size: 8px;
  }
  .action-btn kbd {
    display: none;
  }
  .action-column .action-btn {
    width: 100%;
  }
  .seeker-status {
    flex: 0 0 106px;
    padding-right: 8px;
  }
  .seeker-status strong {
    font-size: 22px;
  }
  .seeker-actions .action-btn {
    min-height: 43px;
    padding: 0 8px;
    font-size: 8.5px;
  }
  .seeker-actions .action-icon {
    display: none;
  }
  .joystick {
    width: 118px;
    height: 118px;
  }
  .joystick-knob {
    width: 48px;
    height: 48px;
    margin: -24px 0 0 -24px;
  }
  .mode-btn {
    min-width: 124px;
    height: 48px;
    font-size: 12px;
    border-radius: 14px;
  }
  .module-btn kbd,
  .mode-btn kbd {
    display: none;
  }
  .hud {
    left: calc(12px + var(--safe-left));
    right: calc(12px + var(--safe-right));
    top: calc(9px + var(--safe-top));
    grid-template-columns: 1fr auto auto;
  }
  .team-badge {
    padding: 4px 8px 4px 7px;
    font-size: 8px;
  }
  .clock-wrap {
    min-width: 108px;
    padding: 6px 12px 7px;
    border-radius: 12px;
  }
  .clock {
    font-size: 22px;
  }
  .clock-label {
    font-size: 6.5px;
  }
  .icon-btn {
    width: 32px;
    height: 32px;
  }
  .toast {
    top: calc(62px + var(--safe-top));
    font-size: 10px;
  }
  .countdown {
    top: 37%;
  }
  .title-screen {
    align-items: flex-start;
    padding: calc(58px + var(--safe-top)) 20px calc(18px + var(--safe-bottom));
    background: linear-gradient(180deg, rgba(4, 11, 8, 0.74), rgba(4, 11, 8, 0.52) 42%, rgba(4, 11, 8, 0.82));
  }
  .title-top {
    top: calc(16px + var(--safe-top));
    left: 20px;
    right: 20px;
  }
  .title-main {
    margin-top: auto;
    margin-bottom: auto;
  }
  .kicker {
    margin-bottom: 8px;
    font-size: 7.5px;
  }
  .wordmark {
    font-size: clamp(3.7rem, 16vw, 5.2rem);
  }
  .lede {
    max-width: 320px;
    margin-top: 12px;
    font-size: 11.5px;
  }
  .role-select {
    gap: 7px;
    margin-top: 17px;
  }
  .role-card {
    grid-template-columns: 1fr;
    align-content: start;
    gap: 7px;
    min-height: 131px;
    padding: 10px;
    border-radius: 12px;
  }
  .role-art {
    width: 38px;
    height: 38px;
  }
  .role-art svg {
    width: 38px;
    height: 31px;
  }
  .role-name {
    font-size: 16px;
  }
